### Python:
```python
class CountDown:
    def __init__(self, start):
        self.start = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.start <= 0:
            raise StopIteration
        self.start -= 1
        return self.start + 1

print(list(CountDown(2)))
```

### JavaScript:
```javascript
const countDown = {
    [Symbol.iterator]() {
        let count = 2;
        return {
            next() {
                if (count > 0) return { value: count--, done: false };
                return { done: true };
            }
        };
    }
};
console.log([...countDown]);
```
